// Only career data is included. Settings, passwords and backups never get reset.
export const BACKUP_KEY = "biplane-save-backup";
export const DEV_PASSWORD_KEY = "biplane-dev-password";
export function careerKey(key:string){return ["biplane-battle-career","biplane-battle-best","biplane-workshop-v1","biplane-campaign-v2","biplane-campaign","biplane-stage-records"].includes(key)||key.startsWith("biplane-battle-daily-")}
export function captureCareer(storage:Storage){const data:Record<string,string>={};for(let i=0;i<storage.length;i++){const key=storage.key(i)!;if(careerKey(key))data[key]=storage.getItem(key)!}return data}
export function readBackup(storage:Storage){const raw=storage.getItem(BACKUP_KEY);if(!raw)return null;const value=JSON.parse(raw);if(!value||typeof value.savedAt!=="string"||!Number.isFinite(Date.parse(value.savedAt))||!value.data||typeof value.data!=="object"||Array.isArray(value.data))throw new Error("Invalid backup");delete value.data["biplane-career-generation"];for(const [key,item] of Object.entries(value.data))if(!careerKey(key)||typeof item!=="string")throw new Error("Invalid backup data");return value as {savedAt:string;data:Record<string,string>}}
export function backupCareer(storage:Storage){const value={savedAt:new Date().toISOString(),data:captureCareer(storage)};storage.setItem(BACKUP_KEY,JSON.stringify(value));return value.savedAt}
export function replaceCareer(storage:Storage,next:Record<string,string>){const previous=captureCareer(storage);try{for(const key of Object.keys(previous))storage.removeItem(key);for(const [key,value] of Object.entries(next)){if(!careerKey(key))throw new Error("Invalid career key");storage.setItem(key,value)}storage.setItem("biplane-career-generation",String(Date.now()))}catch(error){for(const key of Object.keys(captureCareer(storage)))storage.removeItem(key);for(const [key,value] of Object.entries(previous))storage.setItem(key,value);throw error}}
export function resetCareer(storage:Storage){backupCareer(storage);replaceCareer(storage,{})}
export function restoreCareer(storage:Storage){const backup=readBackup(storage);if(!backup)throw new Error("No backup");replaceCareer(storage,backup.data)}
export async function passwordDigest(password:string){const bytes=await crypto.subtle.digest("SHA-256",new TextEncoder().encode("biplane-local-dev:"+password));return Array.from(new Uint8Array(bytes),x=>x.toString(16).padStart(2,"0")).join("")}
