import { LESSONS } from "./mission-catalog";
import { REGIONS, type CampaignState } from "./campaign";
export function missionBrief(c:CampaignState){
 const r=REGIONS[c.region],l=LESSONS[c.stage];
 if(l)return {objective:l.kind==="kills"?"Defeat "+l.target+(l.target===1?" plane":" planes"):l.kind==="rescue"?"Capture "+l.target+" pilots":l.kind==="streak"?"Capture 3 pilots without taking damage":l.kind==="score"?"Earn "+l.target+" mission points":"Survive for "+l.target+" seconds",threat:l.kind==="streak"?"Hull damage resets your capture streak to zero.":"At most "+l.cap+(l.cap===1?" enemy at a time. ":" enemies at once. ")+"Reinforcements replace defeated planes.",tip:l.kind==="rescue"||l.kind==="streak"?"Defeat aircraft, then fly into their falling pilots.":"Use short climbs; release to recover lift. Upgrade engine and wings for longer climbs."};
 if(c.phase==="opening"&&c.region===4)return {objective:"Earn 3,000 points in the mountain pursuit",threat:"Damaged bombers flee over marked rock faces. Stay above the ridges.",tip:"Chase the smoke trail, rescue pilots and chain your takedowns."};
 if(c.phase==="opening")return c.region===2||c.region===4?{objective:"Earn 3,000 points in 90 seconds",threat:"Reinforcements arrive until the target is reached.",tip:"Chain takedowns and catch pilots to multiply points."}:{objective:"Defeat "+c.target+" enemy aircraft",threat:"Enemy patrols defend this sector.",tip:"Strike from above, use short bursts, and rescue pilots."};
 if(c.phase==="specialty"&&c.region===1)return {objective:"Defeat 3 Ironbacks",threat:"Heavy frontal and overhead armor rejects attacks.",tip:"One at a time: circle behind and strike the pink tail."};
 if(c.phase==="specialty"&&c.region===2)return {objective:"Defeat 3 Lancers",threat:"The nose is armored during the charge.",tip:"Evade the straight pass, then strike the pink nose while it cools."};
 if(c.phase==="specialty"&&c.region===4)return {objective:"Defeat 3 specialists",threat:"First, a lone twin-engine aircraft. Mixed attackers follow.",tip:"Destroy both pink engines; attack from above and below. Watch each rival's weak point."};
 if(c.phase==="specialty"&&c.region===3)return {objective:"Defeat 3 attack helicopters",threat:"One gunship at a time. Tracking precedes each guided missile.",tip:"Shoot the missile pods to disarm it, or dodge and strike the exposed belly."};
 if(c.phase==="specialty")return {objective:c.region===0?"Defeat the helicopter from underneath":"Defeat 3 specialist aircraft",threat:c.region===0?"Top rotors are armored and dangerous.":c.region===1?"Cargo noses are armored; their tails are vulnerable.":c.region===2?"Interceptors make fast passes, then slow to turn.":"Mixed vehicles have different protected surfaces.",tip:c.region===0?"Climb into the pink belly, or shoot upward into it.":"Attack glowing weak spots. Cargo planes drop supplies."};
 if(c.phase==="escape")return {objective:"Survive the wreckage for 18 seconds",threat:"Falling wings and engines cross your flight path.",tip:"Brake, turn and change altitude when warnings appear."};
 if(c.phase==="boss")return r.boss==="train"?{objective:"Destroy all four train carriages",threat:"Damaged trains fire faster, wider volleys.",tip:"Shoot turrets to silence their guns, then finish the moving carriages."}:{objective:"Disable the engines, then strike the core",threat:r.boss==="airship"?"Armed mines drift below the airship.":"Interceptor pairs launch from the hangars.",tip:r.boss==="airship"?"Shoot mines with F. Dive onto the glowing engines.":"Strike from above. Watch the incoming bomb spread."};
 if(r.mission==="escort")return {objective:"Protect the transport for 40 seconds",threat:"Pursuers aim their fire at the transport.",tip:c.region===4?"Collect green carrier balloons to repair 2 hull.":"Watch gust warnings, correct your course, and intercept attackers."};
 if(r.mission==="rescue")return {objective:"Rescue 5 pilots",threat:"Enemy fighters keep arriving.",tip:"Fly into falling pilots. Follow the signal flares."};
 if(r.mission==="intercept")return {objective:"Intercept 6 bombers",threat:"The mission fails if 3 bombers escape.",tip:"Prioritize bombers over their fighter escorts."};
 return {objective:"Destroy 3 convoy trucks in 90 seconds",threat:"Trucks move and return fire.",tip:"Tap B to bomb. Climb above marked fuel vents before the flames rise."};
}
