"use client";
import { BAY_STAR_LABELS } from "../lib/kestrel-bay";
import { useState } from "react";
import { ISLAND_TARGETS, fortressDefenses, type IslandTarget, type IslandProgress } from "../lib/island-progress";
export function IslandCommand({progress,credits,onLaunch,onHangar}:{progress:IslandProgress;credits:number;onLaunch:(id:IslandTarget)=>void;onHangar:()=>void}){
 const [selected,setSelected]=useState<IslandTarget>("bay");const t=ISLAND_TARGETS[selected],d=fortressDefenses(progress),locked=selected==="research"&&!progress.discovered;
 return <section className="island-command" aria-label="Carrier command"><header><div><p className="eyebrow">OPERATION BREAKWATER / CONNECTED CAMPAIGN</p><h2>One island. Your strategy.</h2><p>Launch from the Resolute. Break the supply network—or challenge the fortress at full strength.</p></div><span className="island-status">{progress.secured.includes("fortress")?"ISLAND LIBERATED":"ENEMY TERRITORY"}</span></header>
 <div className="island-layout"><div className="island-map" aria-label="Kestrel Island tactical map"><svg viewBox="0 0 800 520" aria-hidden="true"><defs><pattern id="sea-grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#73bdc215"/></pattern><linearGradient id="land" x2="1" y2="1"><stop stopColor="#54796c"/><stop offset="1" stopColor="#203d42"/></linearGradient></defs><rect width="800" height="520" fill="#0b2737"/><rect width="800" height="520" fill="url(#sea-grid)"/><path d="M135 180L185 100 280 110 355 65 435 105 530 75 630 100 715 155 670 220 690 275 605 310 560 395 455 425 380 385 285 420 225 360 140 330 100 265Z" fill="none" stroke="#85b8ae22" strokeWidth="28"/><path d="M135 180L185 100 280 110 355 65 435 105 530 75 630 100 715 155 670 220 690 275 605 310 560 395 455 425 380 385 285 420 225 360 140 330 100 265Z" fill="url(#land)" stroke="#9dc1a4" strokeWidth="2"/><path d="M195 155Q300 200 385 345T540 170L655 100" stroke="#c9b99166" strokeWidth="3" fill="none" strokeDasharray="7 7"/><path d="M300 250L355 160 405 250M360 265L430 145 495 260M460 290L520 200 570 290" fill="#112e3877" stroke="#90aaa133"/><g transform="translate(93 450) rotate(-12)"><path d="M-60-13H45L66 0 45 16H-50Z" fill="#a6bac0"/><path d="M-48-5H43M-40 6H35" stroke="#e7cf8f"/><rect x="-8" y="-25" width="27" height="12" fill="#637e89"/></g><text x="23" y="500" fill="#a6c8d4" fontSize="13" fontFamily="monospace">CV RESOLUTE / HOME PORT</text></svg>
 {(Object.entries(ISLAND_TARGETS) as [IslandTarget,typeof ISLAND_TARGETS[IslandTarget]][]).filter(([id])=>id!=="research"||progress.discovered).map(([id,n])=><button key={id} className={"island-pin "+(progress.secured.includes(id)?"secured ":"")+(selected===id?"selected":"")} style={{left:n.x+"%",top:n.y+"%"}} onClick={()=>setSelected(id)} aria-label={n.name+(progress.secured.includes(id)?" secured":"")} aria-pressed={selected===id}><span>{progress.secured.includes(id)?"✓":id==="fortress"?"✦":"◇"}</span><small>{n.name}</small></button>)}
 </div><aside className="sortie-card"><p className="eyebrow">{t.role}</p><h3>{t.name}</h3><p>{t.objective}</p><div className="sortie-effect"><small>STRATEGIC CONSEQUENCE</small><p>{t.effect}</p></div><p>{selected==="bay"?"Mastery: "+(progress.bayStars?.length??0)+"/5 stars · new stars pay 10 credits each":progress.secured.includes(selected)?"Secured · replay for practice. No repeat credit reward.":"First victory: +"+t.reward+" credits"}</p>{selected==="bay"&&<p>{progress.bayRescue?"✦ Blue Two rescue commendation earned":"Optional: catch Blue Two’s green parachute and return safely. First delivery earns 20 credits."}</p>}{selected==="bay"&&<ul className="bay-result-stars">{BAY_STAR_LABELS.map((label,i)=><li className={progress.bayStars?.includes(i)?"earned":""} key={label}>{progress.bayStars?.includes(i)?"★":"☆"} {label}</li>)}</ul>}<button className="launch" disabled={locked} onClick={()=>onLaunch(selected)}>{selected==="fortress"?"Launch fortress assault":"Launch sortie"} →</button><small>F fires · B drops limited bombs · catch falling personnel to rescue.</small></aside></div>
 <div className="island-intel"><article><small>FORTRESS INTELLIGENCE</small><h3>{d.engineHull*4} engine hull · {d.patrolSize===2?"Paired":"Single"} patrols</h3><p>{d.missiles?"Guided-missile helicopters active":"Radar network neutralized"}</p></article><article><small>RESOLUTE WORKSHOP</small><h3>{credits.toLocaleString()} credits</h3><p>Your owned aircraft and permanent upgrades serve every sortie.</p><button onClick={onHangar}>Visit hangar →</button></article><article><small>RESEARCH DIVISION</small><h3>{progress.secured.includes("research")?"Scientists aboard":progress.discovered?"Station Wraith located":"Classified installation"}</h3><p>{progress.secured.includes("research")?"Fortress flights launch with 15 seconds of protective armor.":progress.discovered?"Rescue its scientists to support the final assault.":"An undiscovered facility lies somewhere in the operation area."}</p>{progress.discovered&&<button onClick={()=>setSelected("research")}>Inspect research sortie →</button>}</article></div>
 </section>;
}
